public class BoundedThreadPool {
    private final int corePoolSize;
    private final int maximumPoolSize;
    private final long keepAliveTime;
    private final BlockingQueue<Runnable> workQueue;
    private final AtomicInteger poolSize = new AtomicInteger(0);
    private final List<Worker> workers = new ArrayList<>();
    private volatile boolean shutdown = false;
    private final Object lock = new Object();

    public BoundedThreadPool(int corePoolSize, int maximumPoolSize, long keepAliveTime) {
        this.corePoolSize = corePoolSize;
        this.maximumPoolSize = maximumPoolSize;
        this.keepAliveTime = keepAliveTime;
        this.workQueue = new LinkedBlockingQueue<>();
    }

    public void execute(Runnable task) {
        if (shutdown) {
            throw new RejectedExecutionException("Thread pool is shutdown");
        }

        int currentPoolSize = poolSize.get();

        // Try to add task to existing worker if pool is at max capacity
        if (currentPoolSize >= maximumPoolSize) {
            if (!workQueue.offer(task)) {
                throw new RejectedExecutionException("Task rejected due to full queue");
            }
            return;
        }

        // Create new worker if needed
        if (currentPoolSize < corePoolSize || 
            (currentPoolSize < maximumPoolSize && !workQueue.isEmpty())) {
            Worker worker = new Worker(task);
            workers.add(worker);
            poolSize.incrementAndGet();
            worker.start();
            return;
        }

        // Add to queue for existing workers
        if (!workQueue.offer(task)) {
            if (poolSize.get() < maximumPoolSize) {
                Worker worker = new Worker(task);
                workers.add(worker);
                poolSize.incrementAndGet();
                worker.start();
            } else {
                throw new RejectedExecutionException("Task rejected due to full queue");
            }
        }
    }

    public void shutdown() {
        shutdown = true;
        synchronized (lock) {
            lock.notifyAll();
        }
    }

    public List<Runnable> shutdownNow() {
        shutdown = true;
        List<Runnable> pendingTasks = new ArrayList<>();

        synchronized (lock) {
            for (Worker worker : workers) {
                worker.interrupt();
            }
            workQueue.drainTo(pendingTasks);
            lock.notifyAll();
        }

        return pendingTasks;
    }

    public boolean isShutdown() {
        return shutdown;
    }

    public boolean isTerminated() {
        if (!shutdown) return false;
        for (Worker worker : workers) {
            if (!worker.isTerminated()) {
                return false;
            }
        }
        return true;
    }

    public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
        long nanos = unit.toNanos(timeout);
        long deadline = System.nanoTime() + nanos;

        synchronized (lock) {
            while (!isTerminated() && nanos > 0) {
                TimeUnit.NANOSECONDS.timedWait(lock, nanos);
                nanos = deadline - System.nanoTime();
            }
        }
        return isTerminated();
    }

    private class Worker extends Thread {
        private Runnable firstTask;
        private volatile boolean terminated = false;

        Worker(Runnable firstTask) {
            this.firstTask = firstTask;
        }

